-- Writing: Medium articles and YouTube videos for the Articles section.
-- Run in the Supabase SQL editor. Safe to re-run.
--
-- 1. Adds the 15 posts that are not on the site yet (7 Medium articles,
--    8 YouTube videos), matched by the article/video id so a different URL
--    form of the same post is not added twice. AI/ML posts go to every
--    version; general web/dev posts go to the Developer version only.
--    None are on the home page; switch that on in batools.
-- 2. For the 6 posts already on the site, fills only fields that are still
--    empty (Bangla title and summary, tags, reading time). Nothing you
--    wrote is overwritten.
--
-- Sources: the Medium RSS feed and the YouTube channel feed (read 2026-10-31).
-- LinkedIn needs a sign-in, so no LinkedIn posts were added.

BEGIN;

INSERT INTO pf_posts (user_id, kind, platform, external_url, title_en, title_bn, summary_en, summary_bn,
                      cover_url, tags, published_at, reading_minutes, versions, sort_order, show_on_home, status)
SELECT '88b3efb5-8c58-486e-a3f7-751cc4b23e60', 'external', v.platform, v.url, v.title_en, v.title_bn,
       v.summary_en, v.summary_bn, v.cover, v.tags, v.published, v.minutes, v.versions, v.sort, false, 'published'
FROM (VALUES
  ($q$medium$q$, $q$https://abir-hosen-ashik.medium.com/what-do-i-want-software-engineer-career-objective-dc2cc4f8f80b$q$, $q$dc2cc4f8f80b$q$, $q$What Do I Want? A Software Engineer's Career Objective$q$, $q$আমি কী চাই? একজন সফটওয়্যার ইঞ্জিনিয়ারের ক্যারিয়ার লক্ষ্য$q$, $q$A career objective answers three questions: who am I, what do I want, and what do I offer. This piece takes the second one and works through it stage by stage, from junior developer onward, to help engineers turn a vague ambition into a clear focus and a plan for the next step.$q$, $q$ক্যারিয়ার লক্ষ্য তিনটি প্রশ্নের উত্তর দেয়: আমি কে, আমি কী চাই, আর আমি কী দিতে পারি। এই লেখায় দ্বিতীয় প্রশ্নটি নিয়ে জুনিয়র ডেভেলপার থেকে শুরু করে ক্যারিয়ারের প্রতিটি ধাপে আলোচনা করা হয়েছে, যাতে অস্পষ্ট ইচ্ছাকে স্পষ্ট লক্ষ্য ও পরের ধাপের পরিকল্পনায় রূপ দেওয়া যায়।$q$, $q$https://miro.medium.com/v2/resize:fit:720/format:webp/1*MQ32S6Ha0dx2LBkzaI2ldQ.jpeg$q$, ARRAY[$q$Career$q$, $q$Software Engineering$q$, $q$Goals$q$]::text[], DATE '2025-09-06', 3, ARRAY[$q$0200534f-0734-448c-804f-5d490b777501$q$]::uuid[], 7),
  ($q$medium$q$, $q$https://abir-hosen-ashik.medium.com/building-a-sentiment-analysis-model-with-transformer-embeddings-a-comprehensive-approach-f6ed91656d46$q$, $q$f6ed91656d46$q$, $q$Building a Sentiment Analysis Model with Transformer Embeddings$q$, $q$ট্রান্সফরমার এমবেডিং দিয়ে অনুভূতি বিশ্লেষণ মডেল তৈরি$q$, $q$A step-by-step walk-through of a Kaggle notebook that classifies the 50,000 IMDb movie reviews as positive or negative. It turns each review into a transformer sentence embedding, trains neural-network classifiers on top, explains why each library was chosen, and closes with ideas for improving the model. This work grew into the movie-review sentiment model published on Hugging Face.$q$, $q$একটি Kaggle নোটবুকের ধাপে ধাপে ব্যাখ্যা, যা IMDb-এর ৫০,০০০ সিনেমা রিভিউকে ইতিবাচক বা নেতিবাচক হিসেবে শ্রেণিবদ্ধ করে। প্রতিটি রিভিউকে ট্রান্সফরমার সেন্টেন্স এমবেডিংয়ে রূপান্তর করে তার ওপর নিউরাল নেটওয়ার্ক ক্লাসিফায়ার প্রশিক্ষণ, প্রতিটি লাইব্রেরি বাছাইয়ের কারণ, এবং মডেল উন্নত করার ভাবনা। এই কাজ থেকেই Hugging Face-এ প্রকাশিত সিনেমা রিভিউ অনুভূতি মডেলটি তৈরি।$q$, $q$https://miro.medium.com/v2/resize:fit:720/format:webp/1*u27S8QgBerUSAbh1OR6L1A.png$q$, ARRAY[$q$NLP$q$, $q$Sentiment Analysis$q$, $q$Sentence Transformers$q$, $q$Embeddings$q$, $q$Kaggle$q$]::text[], DATE '2025-03-18', 4, '{}'::uuid[], 8),
  ($q$medium$q$, $q$https://abir-hosen-ashik.medium.com/job-vs-applicant-skill-matcher-a-smart-approach-to-hiring-18e0f93bf59d$q$, $q$18e0f93bf59d$q$, $q$Job vs Applicant Skill Matcher: A Smart Approach to Hiring$q$, $q$চাকরি ও আবেদনকারীর দক্ষতা মেলানো: নিয়োগের একটি স্মার্ট পদ্ধতি$q$, $q$Manual CV screening is slow and subjective. This article shows how transformer embeddings and cosine similarity can match the skills in a job description against each applicant's skills and rank candidates automatically, with a complete Kaggle notebook to follow along.$q$, $q$হাতে সিভি যাচাই ধীর ও ব্যক্তিনির্ভর। এই লেখায় দেখানো হয়েছে কীভাবে ট্রান্সফরমার এমবেডিং ও কোসাইন সিমিলারিটি দিয়ে চাকরির বিবরণের দক্ষতা প্রতিটি আবেদনকারীর দক্ষতার সাথে মিলিয়ে স্বয়ংক্রিয়ভাবে প্রার্থীদের র‍্যাঙ্ক করা যায়, সাথে অনুসরণের জন্য পূর্ণ Kaggle নোটবুক।$q$, $q$https://miro.medium.com/v2/resize:fit:720/format:webp/1*J-j1VvBym5_pDbGtLw4aLg.png$q$, ARRAY[$q$Embeddings$q$, $q$Transformers$q$, $q$Cosine Similarity$q$, $q$Recruiting AI$q$]::text[], DATE '2025-03-14', 2, '{}'::uuid[], 9),
  ($q$medium$q$, $q$https://abir-hosen-ashik.medium.com/mongodb-a-comprehensive-overview-of-server-shell-and-compass-c5d2fd2449d4$q$, $q$c5d2fd2449d4$q$, $q$MongoDB: A Comprehensive Overview of Server, Shell and Compass$q$, $q$MongoDB: সার্ভার, শেল ও কম্পাসের পূর্ণাঙ্গ পরিচিতি$q$, $q$An introduction to MongoDB's document model and its three core tools: the server (mongod) that stores, indexes and queries data, the shell for working with it from the command line, and Compass, the graphical client for exploring and managing collections.$q$, $q$MongoDB-র ডকুমেন্ট মডেল ও এর তিনটি মূল টুলের পরিচিতি: ডেটা সংরক্ষণ, ইনডেক্সিং ও কোয়েরি সামলানো সার্ভার (mongod), কমান্ড লাইন থেকে কাজ করার শেল, এবং কালেকশন দেখা ও পরিচালনার গ্রাফিক্যাল ক্লায়েন্ট কম্পাস।$q$, $q$https://miro.medium.com/v2/resize:fit:720/format:webp/0*_HlL0AWCzIxHxvqy.png$q$, ARRAY[$q$MongoDB$q$, $q$NoSQL$q$, $q$Databases$q$]::text[], DATE '2025-03-04', 5, ARRAY[$q$0200534f-0734-448c-804f-5d490b777501$q$]::uuid[], 10),
  ($q$medium$q$, $q$https://abir-hosen-ashik.medium.com/encoder-only-transformer-based-classification-with-a-simple-version-of-model-building-training-128bf8df688b$q$, $q$128bf8df688b$q$, $q$Encoder-Only Transformer Classification: Building, Training and Testing a Simple Model$q$, $q$এনকোডার-অনলি ট্রান্সফরমার দিয়ে শ্রেণিকরণ: একটি সহজ মডেল তৈরি, প্রশিক্ষণ ও পরীক্ষা$q$, $q$Starting from "Attention Is All You Need", this article explains why transformers process all tokens in parallel instead of step by step like RNNs, then builds a small encoder-only transformer for text classification from scratch and walks through training and testing it.$q$, $q$"Attention Is All You Need" থেকে শুরু করে এই লেখায় ব্যাখ্যা করা হয়েছে কেন ট্রান্সফরমার RNN-এর মতো একটি একটি করে নয়, সব টোকেন একসাথে প্রসেস করে; তারপর টেক্সট শ্রেণিকরণের জন্য শূন্য থেকে একটি ছোট এনকোডার-অনলি ট্রান্সফরমার তৈরি করে প্রশিক্ষণ ও পরীক্ষা দেখানো হয়েছে।$q$, $q$https://miro.medium.com/v2/resize:fit:720/format:webp/1*43LfZP5McwHsxJNrdfWwhQ.png$q$, ARRAY[$q$Transformers$q$, $q$Deep Learning$q$, $q$Text Classification$q$, $q$PyTorch$q$]::text[], DATE '2025-03-02', 7, '{}'::uuid[], 11),
  ($q$medium$q$, $q$https://abir-hosen-ashik.medium.com/precision-recall-and-f1-score-in-banglish-b08f9653674b$q$, $q$b08f9653674b$q$, $q$Precision, Recall and F1 Score in Banglish$q$, $q$প্রিসিশন, রিকল ও F1 স্কোর (বাংলায়)$q$, $q$Classification metrics explained in Bangla for Bangla-speaking learners. Using a disease-diagnosis example, it defines true and false positives and negatives, then builds up precision, recall and the F1 score and when each one matters.$q$, $q$বাংলাভাষী শিক্ষার্থীদের জন্য বাংলায় ক্লাসিফিকেশন মেট্রিকের ব্যাখ্যা। রোগ নির্ণয়ের উদাহরণ দিয়ে ট্রু ও ফলস পজিটিভ-নেগেটিভ বোঝানো, তারপর প্রিসিশন, রিকল ও F1 স্কোর এবং কখন কোনটি গুরুত্বপূর্ণ।$q$, $q$https://miro.medium.com/v2/resize:fit:720/format:webp/1*KU8fE2JkcuY15pscX4sLZA.png$q$, ARRAY[$q$Machine Learning$q$, $q$Evaluation Metrics$q$, $q$Bangla$q$]::text[], DATE '2025-02-27', 3, '{}'::uuid[], 12),
  ($q$medium$q$, $q$https://abir-hosen-ashik.medium.com/cbow-skip-gram-fc69bf829b02$q$, $q$fc69bf829b02$q$, $q$CBOW and Skip-gram: The Two Word2Vec Architectures$q$, $q$CBOW ও Skip-gram: Word2Vec-এর দুটি আর্কিটেকচার$q$, $q$A short Bangla explainer of Word2Vec's two ways of learning word vectors: CBOW predicts a word from its surrounding context, while Skip-gram predicts the context from the word, both worked through on one example sentence.$q$, $q$Word2Vec-এর শব্দ-ভেক্টর শেখার দুটি পদ্ধতির সংক্ষিপ্ত বাংলা ব্যাখ্যা: CBOW আশেপাশের শব্দ থেকে মাঝের শব্দ অনুমান করে, আর Skip-gram শব্দ থেকে আশেপাশের শব্দ; দুটোই একটি উদাহরণ বাক্যে দেখানো হয়েছে।$q$, $q$https://miro.medium.com/v2/resize:fit:720/format:webp/1*AFwJYbT75kbu0opEwtCq3g.png$q$, ARRAY[$q$NLP$q$, $q$Word2Vec$q$, $q$Embeddings$q$, $q$Bangla$q$]::text[], DATE '2025-02-20', 1, '{}'::uuid[], 13),
  ($q$youtube$q$, $q$https://youtu.be/78x5b3xhn60$q$, $q$78x5b3xhn60$q$, $q$Abir Hosen, Software Engineer: Intro Video$q$, $q$আবির হোসেন, সফটওয়্যার ইঞ্জিনিয়ার: পরিচিতি ভিডিও$q$, $q$A short video introduction: who I am, the kind of software I build and how I work.$q$, $q$একটি সংক্ষিপ্ত পরিচিতি ভিডিও: আমি কে, কী ধরনের সফটওয়্যার তৈরি করি এবং কীভাবে কাজ করি।$q$, $q$https://img.youtube.com/vi/78x5b3xhn60/hqdefault.jpg$q$, ARRAY[$q$Introduction$q$, $q$Software Engineering$q$]::text[], DATE '2025-07-28', NULL, ARRAY[$q$0200534f-0734-448c-804f-5d490b777501$q$]::uuid[], 14),
  ($q$youtube$q$, $q$https://youtu.be/XPxFMGZZ33Q$q$, $q$XPxFMGZZ33Q$q$, $q$PyTorch vs TensorFlow$q$, $q$PyTorch বনাম TensorFlow$q$, $q$A quick comparison of the two main deep-learning frameworks, PyTorch and TensorFlow, and what to weigh when choosing one.$q$, $q$দুটি প্রধান ডিপ লার্নিং ফ্রেমওয়ার্ক PyTorch ও TensorFlow-এর দ্রুত তুলনা, এবং কোনটি বেছে নেবেন তা ঠিক করতে কী বিবেচনা করবেন।$q$, $q$https://img.youtube.com/vi/XPxFMGZZ33Q/hqdefault.jpg$q$, ARRAY[$q$PyTorch$q$, $q$TensorFlow$q$, $q$Deep Learning$q$]::text[], DATE '2024-10-19', NULL, '{}'::uuid[], 15),
  ($q$youtube$q$, $q$https://youtu.be/Y4bAr6rYoy4$q$, $q$Y4bAr6rYoy4$q$, $q$An Overview of AI, Machine Learning and Deep Learning$q$, $q$এআই, মেশিন লার্নিং ও ডিপ লার্নিংয়ের পরিচিতি$q$, $q$A short overview of how artificial intelligence, machine learning, deep learning and neural networks relate to one another.$q$, $q$কৃত্রিম বুদ্ধিমত্তা, মেশিন লার্নিং, ডিপ লার্নিং ও নিউরাল নেটওয়ার্ক একে অপরের সাথে কীভাবে সম্পর্কিত তার সংক্ষিপ্ত পরিচিতি।$q$, $q$https://img.youtube.com/vi/Y4bAr6rYoy4/hqdefault.jpg$q$, ARRAY[$q$AI$q$, $q$Machine Learning$q$, $q$Deep Learning$q$]::text[], DATE '2024-07-01', NULL, '{}'::uuid[], 16),
  ($q$youtube$q$, $q$https://youtu.be/X7Sbe7adoQk$q$, $q$X7Sbe7adoQk$q$, $q$The Fetch API in JavaScript$q$, $q$জাভাস্ক্রিপ্টে Fetch API$q$, $q$A short guide to calling APIs from the browser with JavaScript's built-in fetch.$q$, $q$জাভাস্ক্রিপ্টের নিজস্ব fetch দিয়ে ব্রাউজার থেকে API কল করার সংক্ষিপ্ত গাইড।$q$, $q$https://img.youtube.com/vi/X7Sbe7adoQk/hqdefault.jpg$q$, ARRAY[$q$JavaScript$q$, $q$APIs$q$, $q$Frontend$q$]::text[], DATE '2024-07-16', NULL, ARRAY[$q$0200534f-0734-448c-804f-5d490b777501$q$]::uuid[], 17),
  ($q$youtube$q$, $q$https://youtu.be/-GchvSqj6-E$q$, $q$-GchvSqj6-E$q$, $q$Algorithm Basics$q$, $q$অ্যালগরিদমের মূল ধারণা$q$, $q$A short introduction to what an algorithm is and the basic ideas behind designing one.$q$, $q$অ্যালগরিদম কী এবং তা নকশার মূল ধারণাগুলোর সংক্ষিপ্ত পরিচিতি।$q$, $q$https://img.youtube.com/vi/-GchvSqj6-E/hqdefault.jpg$q$, ARRAY[$q$Algorithms$q$, $q$Computer Science$q$]::text[], DATE '2024-07-02', NULL, ARRAY[$q$0200534f-0734-448c-804f-5d490b777501$q$]::uuid[], 18),
  ($q$youtube$q$, $q$https://youtu.be/XLdjBtVZELc$q$, $q$XLdjBtVZELc$q$, $q$ReactJS vs Next.js$q$, $q$ReactJS বনাম Next.js$q$, $q$A quick comparison of React and Next.js for frontend developers: what each one gives you and when to reach for which.$q$, $q$ফ্রন্টএন্ড ডেভেলপারদের জন্য React ও Next.js-এর দ্রুত তুলনা: কোনটি কী সুবিধা দেয় এবং কখন কোনটি ব্যবহার করবেন।$q$, $q$https://img.youtube.com/vi/XLdjBtVZELc/hqdefault.jpg$q$, ARRAY[$q$React$q$, $q$Next.js$q$, $q$Frontend$q$]::text[], DATE '2024-06-30', NULL, ARRAY[$q$0200534f-0734-448c-804f-5d490b777501$q$]::uuid[], 19),
  ($q$youtube$q$, $q$https://youtu.be/Qw_8PMlU-lg$q$, $q$Qw_8PMlU-lg$q$, $q$JavaScript Tricks for Clean Code$q$, $q$পরিষ্কার কোডের জন্য জাভাস্ক্রিপ্ট কৌশল$q$, $q$Short JavaScript tips that make everyday code cleaner and easier to read.$q$, $q$দৈনন্দিন কোডকে পরিষ্কার ও সহজপাঠ্য করার ছোট ছোট জাভাস্ক্রিপ্ট টিপস।$q$, $q$https://img.youtube.com/vi/Qw_8PMlU-lg/hqdefault.jpg$q$, ARRAY[$q$JavaScript$q$, $q$Clean Code$q$]::text[], DATE '2024-06-27', NULL, ARRAY[$q$0200534f-0734-448c-804f-5d490b777501$q$]::uuid[], 20),
  ($q$youtube$q$, $q$https://youtu.be/Af22pYsLDRk$q$, $q$Af22pYsLDRk$q$, $q$Deploying a Cron Job on Render.com$q$, $q$Render.com-এ ক্রন জব ডিপ্লয়$q$, $q$A walk-through of setting up and deploying a scheduled cron job on the Render cloud platform.$q$, $q$Render ক্লাউড প্ল্যাটফর্মে নির্ধারিত ক্রন জব সেটআপ ও ডিপ্লয় করার ধাপে ধাপে দেখানো।$q$, $q$https://img.youtube.com/vi/Af22pYsLDRk/hqdefault.jpg$q$, ARRAY[$q$Cron Jobs$q$, $q$Deployment$q$, $q$Render$q$]::text[], DATE '2023-09-05', NULL, ARRAY[$q$0200534f-0734-448c-804f-5d490b777501$q$]::uuid[], 21)
) AS v(platform, url, match, title_en, title_bn, summary_en, summary_bn, cover, tags, published, minutes, versions, sort)
WHERE NOT EXISTS (
  SELECT 1 FROM pf_posts p
  WHERE p.user_id = '88b3efb5-8c58-486e-a3f7-751cc4b23e60' AND p.external_url LIKE '%' || v.match || '%'
);

UPDATE pf_posts p SET
  title_bn = CASE WHEN p.title_bn = '' THEN v.title_bn ELSE p.title_bn END,
  summary_bn = COALESCE(NULLIF(p.summary_bn, ''), v.summary_bn),
  tags = CASE WHEN p.tags = '{}' THEN v.tags ELSE p.tags END,
  reading_minutes = COALESCE(p.reading_minutes, v.minutes)
FROM (VALUES
